// Turns the contracts' JSON Schema (written by tools/play_schema.py) into TypeScript on stdout.
// usage: node tools/schema-to-ts.mjs <schema.json>
import { readFileSync } from 'node:fs';
import { compile } from 'json-schema-to-typescript';

const schema = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const ts = await compile(schema, 'FrxContracts', {
  bannerComment:
    '/* Generated by tools/play_schema.py from apps/api/frx/play_models.py. Do not edit by hand. */',
  additionalProperties: false,
  unreachableDefinitions: true,
  declareExternallyReferenced: true,
  enableConstEnums: false,
  strictIndexSignatures: true,
  format: true,
  style: { singleQuote: true, printWidth: 100 },
});
process.stdout.write(ts);
